        [global::System.Configuration.DefaultSettingValueAttribute(@"SELECT m1.DOC_NO as FBillNo,m1.DOC_DATE as FDate,i1.ITEM_CODE as FNumber,i1.ITEM_NAME as FName,i1.ITEM_SPECIFICATION as FModel
